package com.myaaptha.domain.finance;
import java.security.Principal;import java.time.YearMonth;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/finance") public class FinanceController{private final FinanceService service;public FinanceController(FinanceService s){service=s;}@GetMapping("/summary")public FinanceService.Summary summary(Principal p,@RequestParam(required=false)String month){return service.summary(id(p),requestedMonth(month));}@PostMapping("/transactions")public FinanceService.Transaction add(Principal p,@RequestBody FinanceService.Input input){return service.add(id(p),input);}@DeleteMapping("/transactions/{id}")public ResponseEntity<Void> delete(Principal p,@PathVariable Long id){service.delete(id(p),id);return ResponseEntity.noContent().build();}private YearMonth requestedMonth(String month){if(month==null)return YearMonth.now(java.time.ZoneOffset.UTC);if(!month.matches("(?!0000)[0-9]{4}-(0[1-9]|1[0-2])"))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Use a valid month in YYYY-MM format");return YearMonth.parse(month);}private Long id(Principal p){return Long.valueOf(p.getName());}}
